import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/190_blobid1.BSR5oLMv.png",s="/assets/192_blobid2.eqKyt2e3.png",i="/assets/195_blobid3.C4BYoLD4.png",d="/assets/194_blobid4.B1M7Iivk.png",v=JSON.parse('{"title":"BMC Reset on Dedicated Server","description":"","frontmatter":{"title":"BMC Reset on Dedicated Server"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/bmc-reset-on-dedicated-server.md","filePath":"operations-knowledge-base/dedicated-server/bmc-reset-on-dedicated-server.md","lastUpdated":1794292919000}'),l={name:"operations-knowledge-base/dedicated-server/bmc-reset-on-dedicated-server.md"};function c(p,e,m,u,g,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>Introduction: Server BMC (Baseboard Management Controller) is an embedded system typically integrated into server hardware, providing remote management and monitoring capabilities. BMC is primarily used for monitoring the hardware status, managing system configurations, executing remote control, and performing fault diagnosis tasks on Dedicated Server. It enables administrators to remotely manage servers without being on-site.</p><p>Functionality:</p><p>Hardware Monitoring: BMC can monitor hardware information such as server temperature, fan speed, power supply, and issue alerts to prevent data loss and downtime caused by hardware failures.</p><p>Remote Management: BMC enables remote connectivity to servers over the network, allowing tasks such as power on/off, reboot, and modification of BIOS settings. This improves server reliability and maintainability.</p><p>System Configuration: BMC provides a graphical interface for system configuration, including IP address, DNS settings, time synchronization, and more.</p><p>Logging: BMC logs server operational details, including hardware failures, system events, and security incidents. This helps administrators with troubleshooting and security auditing.</p><p>For example:</p><p>If you are unable to open VNC in the background, you could try resetting the BMC.</p><p>If you have forgotten the login credentials for BMC and cannot access the management and configuration interface.</p><p>If there are issues with BMC configuration, preventing remote management and monitoring.</p><p>If you encounter performance problems with BMC, such as inability to access or slow responsiveness.</p><p>If you need to update or upgrade the BMC firmware.</p><p>In these situations, attempting to reset the BMC may help resolve the issues. The method for resetting the BMC varies depending on the hardware platform.</p><ol><li>Select the physical server that you wish to manage.</li></ol><p>Log in to the platform and enter the **Customer Center**. Click **&quot;My Orders&quot;** at the bottom, then select **&quot;Bare Metal Server&quot;**. Alternatively, go to **&quot;Product Management&quot;** and click **&quot;Bare Metal Server&quot;**, then filter by the region and status of your server.</p><ol start="2"><li>After locating the corresponding physical server, click on &quot;Reset BMC&quot; to initiate the reset process.</li></ol><p><img src="'+n+'" alt=""></p><p><img src="'+s+'" alt=""></p><ol start="3"><li>You will receive a notification confirming the successful reset of BMC. It usually takes around 5 minutes before you can establish a connection.</li></ol><p><img src="'+i+'" alt=""></p><ol start="4"><li>You can also perform a BMC reset from the control panel.</li></ol><p><img src="'+d+'" alt=""></p>',22)])])}const y=t(l,[["render",c]]);export{v as __pageData,y as default};
